import {test,expect} from '@playwright/test';
const uid=n=>`00000000-0000-0000-0000-${String(n).padStart(12,'0')}`;
test('two users create a group, publish and reserve points through the browser',async({browser},testInfo)=>{
  const contexts=[];const errors=[];let group=null,bet=null,prediction=null,friendship=null,joinedAfter=0,lostResponse=false;const members=new Set(['owner']);const messages=[],privateMessages=[];
  async function pageFor(){const context=await browser.newContext({viewport:{width:1440,height:1000}});contexts.push(context);const page=await context.newPage();page.on('pageerror',error=>errors.push(error.message));page.on('console',message=>{if(message.type()==='error')console.log('Browser:',message.text());});
    await page.route('**/status',route=>route.fulfill({json:{writer:true,reader:true}}));
    await page.route('**/auth/v1/**',async route=>{const request=route.request(),path=new URL(request.url()).pathname;const headers={'access-control-allow-origin':'*','access-control-allow-headers':'apikey,content-type,authorization','access-control-allow-methods':'POST,OPTIONS'};if(request.method()==='OPTIONS')return route.fulfill({status:204,headers});if(path.endsWith('/logout'))return route.fulfill({json:{},headers});const body=request.postDataJSON(),role=body.email?.startsWith('owner')?'owner':'participant';return route.fulfill({headers,json:{access_token:role,refresh_token:role,expires_in:3600,user:{email:`${role}@example.test`,user_metadata:{display_name:role==='owner'?'Marco':'Ana'}}}});});
    await page.route('**/writer/api/**',async route=>{const req=route.request(),path=new URL(req.url()).pathname.replace('/writer',''),method=req.method(),role=req.headers().authorization?.replace('Bearer ','')||'owner',id=role==='owner'?uid(1):uid(2);let json={};let status=200;
      if(path.endsWith('/resolution'))json={state:bet.state,phase:'IN_PROGRESS',resultDeadline:new Date(Date.now()+7200000).toISOString(),contestDeadline:null,publishedOptionId:null,finalOptionId:null,concludedAt:null,conclusionReason:null,pendingContests:0,myPendingContest:false,canPublishResult:false,canContest:false,canDecide:false,canCancel:role==='owner',myCredit:null,myMovement:null,lastDecisionAction:null};
      else if(path.endsWith('/settings'))json={...group,initialPoints:100,dailyPoints:0,settlementSeconds:3600,contestSeconds:3600,invitePolicy:'ALL_MEMBERS',myRole:role==='owner'?'OWNER':'MEMBER',canInvite:true};
      else if(path==='/api/group-invitations')json=[];
      else if(path==='/api/users')json=[{id:uid(2),displayName:'Ana'}];
      else if(path==='/api/friendships'&&method==='GET')json=friendship?[{id:uid(8),userId:role==='owner'?uid(2):uid(1),displayName:role==='owner'?'Ana':'Marco',status:friendship,incoming:role==='participant'}]:[];
      else if(path==='/api/friendships'){friendship='PENDING';json={id:uid(8),userId:uid(2),displayName:'Ana',status:friendship,incoming:false};}
      else if(path.endsWith('/accept')){friendship='ACCEPTED';json={};}
      else if(path.includes('/messages')) {
        const privateChat=path.includes('/friends/'),list=privateChat?privateMessages:messages;
        if(path.endsWith('/delete')){const message=list.find(m=>m.id===Number(path.split('/').at(-2)));message.body=null;message.deleted=true;}
        else if(method==='POST'){const payload=req.postDataJSON();if(!list.some(m=>m.clientId===payload.clientId&&m.authorId===id))list.push({id:list.length+1,clientId:payload.clientId,authorId:id,displayName:role==='owner'?'Marco':'Ana',body:payload.body,sentAt:new Date().toISOString(),deleted:false});if(payload.body==='Envio com resposta perdida'&&!lostResponse){lostResponse=true;status=503;json={code:'SERVICE_UNAVAILABLE',message:'Resposta perdida. Confira a conversa antes de repetir.'};}}
        else json={messages:list.filter(m=>privateChat||role==='owner'||m.id>joinedAfter),nextBefore:null,canModerate:!privateChat&&role==='owner'};
      }
      else if(path==='/api/me')json={id,displayName:role==='owner'?'Marco':'Ana'};
      else if(path==='/api/groups'&&method==='POST'){const body=req.postDataJSON();group={id:uid(3),ownerId:uid(1),name:body.name,visibility:'PUBLIC',entryMode:'IMMEDIATE',member:true,memberCount:1};json=group;status=201;}
      else if(path==='/api/groups')json=group&&members.has(role)?[{...group,memberCount:members.size}]:[];
      else if(path==='/api/groups/public')json=group?[{...group,member:members.has(role),memberCount:members.size}]:[];
      else if(path.endsWith('/members/me')){members.add(role);joinedAfter=messages.length;json={availablePoints:100,reservedPoints:0};}
      else if(path.endsWith('/wallet/me'))json={availablePoints:role==='participant'&&prediction?70:100,reservedPoints:role==='participant'&&prediction?30:0};
      else if(path.endsWith('/bets')&&method==='POST'){const body=req.postDataJSON(),publishedAt=new Date().toISOString();bet={...body,id:uid(4),groupId:uid(3),authorId:uid(1),state:'OPEN',publishedAt,predictionsCloseAt:new Date(Date.now()+3000000).toISOString(),authorCancelUntil:new Date(Date.now()+300000).toISOString(),options:[{id:uid(5),label:'Sim',position:0},{id:uid(6),label:'Não',position:1}]};json=bet;status=201;}
      else if(path.endsWith('/bets'))json=bet?[{bet,myPrediction:role==='participant'?prediction:null}]:[];
      else if(path.endsWith('/predictions')){prediction={id:uid(7),optionId:uid(5),points:30,betId:uid(4),confirmedAt:new Date().toISOString()};json=prediction;status=201;}
      else {status=404;json={code:'NOT_FOUND',message:'Recurso não encontrado.'};}
      await route.fulfill({status,json});});
    await page.route('**/reader/api/**',route=>{const path=new URL(route.request().url()).pathname;const ranking=[{position:1,userId:uid(1),displayName:'Marco',availablePoints:'100'},...(members.has('participant')?[{position:2,userId:uid(2),displayName:'Ana',availablePoints:prediction?'70':'100'}]:[])];return route.fulfill({json:path.endsWith('/ranking')?{groupId:uid(3),ranking}:{betId:uid(4),groupId:uid(3),totalVotes:prediction?1:0,options:[{optionId:uid(5),votes:prediction?1:0,decimalOdds:prediction?'1.00':null},{optionId:uid(6),votes:0,decimalOdds:null}]}});});
    return page;
  }
  try{const owner=await pageFor();await owner.goto('/');await owner.screenshot({path:testInfo.outputPath('login.png'),fullPage:true});await owner.getByLabel('E-mail',{exact:true}).fill('owner@example.test');await owner.getByLabel('Senha',{exact:true}).fill('test-password');await owner.locator('#auth-submit').click();await expect(owner.locator('#app-view')).toBeVisible();
    await owner.locator('#new-group-button').click();await owner.getByLabel('Nome do grupo',{exact:true}).fill('Turma de sexta');await owner.locator('#group-form button[type=submit]').click();await expect(owner.locator('#page-title')).toHaveText('Turma de sexta');
    await owner.locator('#new-bet-button').click();await owner.locator('#bet-type').selectOption('MULTIPLE_CHOICE');await owner.keyboard.press('Escape');await owner.locator('#new-bet-button').click();await owner.getByLabel('Pergunta',{exact:true}).fill('Vai chover no jogo?');await owner.locator('#bet-form button[type=submit]').click();await expect(owner.locator('#bet-detail')).toContainText('Você publicou esta aposta');
    await owner.locator('#group-message').fill('Mensagem anterior à entrada');await owner.locator('#group-send').click();await expect(owner.locator('#group-thread')).toContainText('Mensagem anterior à entrada');
    const participant=await pageFor();await participant.goto('/');await participant.getByLabel('E-mail',{exact:true}).fill('participant@example.test');await participant.getByLabel('Senha',{exact:true}).fill('test-password');await participant.locator('#auth-submit').click();await participant.getByRole('button',{name:'Entrar no grupo ↗'}).click();
    await expect(participant.locator('#group-message')).toBeEnabled();await expect(participant.locator('#group-thread')).not.toContainText('Mensagem anterior à entrada');await participant.locator('#group-message').fill('Olá, turma! <script>texto seguro</script>');await participant.locator('#group-message').press('Enter');await expect(participant.locator('#group-thread')).toContainText('Olá, turma! <script>texto seguro</script>');await expect(participant.locator('#group-thread script')).toHaveCount(0);
    await expect(participant.locator('#available-points')).toHaveText('100');await participant.locator('#prediction-form input[type=radio]').first().check();await participant.getByLabel('Quanto você quer reservar?').fill('30');await participant.getByRole('button',{name:'Confirmar palpite ↗'}).click();await expect(participant.locator('#available-points')).toHaveText('70');await expect(participant.locator('#reserved-points')).toHaveText('30');await expect(participant.locator('.confirmed-box')).toContainText('30 pontos reservados');
    await owner.locator('#refresh-button').click();await expect(owner.locator('[data-odd]').first()).toHaveText('1,00');await expect(owner.locator('#ranking-list')).toContainText('Ana');await owner.screenshot({path:testInfo.outputPath('group-desktop.png'),fullPage:true});
    const left=await owner.locator('.sidebar').boundingBox(),center=await owner.locator('#group-view').boundingBox(),right=await owner.locator('#betting-column').boundingBox();expect(left.x+left.width).toBeLessThan(center.x);expect(center.x+center.width).toBeLessThan(right.x);
    await expect(owner.locator('#group-message')).toBeEnabled();await expect(owner.locator('#friends-list')).toContainText('Nenhuma amizade ainda');await expect(owner.locator('#group-thread')).toContainText('Olá, turma!');await owner.locator('#group-thread .chat-message').last().getByRole('button',{name:'Apagar mensagem de Ana'}).click();await expect(participant.locator('#group-thread')).toContainText('Mensagem apagada pela moderação.');
    await owner.locator('#messages-button').click();await expect(owner.locator('#private-view')).toBeVisible();await expect(owner.locator('#private-message')).toBeDisabled();await expect(owner.locator('#betting-column')).toBeHidden();await expect(owner.locator('#bet-detail')).toBeEmpty();await owner.screenshot({path:testInfo.outputPath('private-desktop.png'),fullPage:true});
    await owner.locator('#group-list button').first().click();await expect(owner.locator('#bet-detail')).toBeVisible();await expect(owner.locator('#private-view')).toBeHidden();
    await participant.locator('#group-message').fill('Envio com resposta perdida');await participant.locator('#group-send').click();await expect(participant.locator('#group-error')).toContainText('Resposta perdida');await participant.waitForTimeout(3500);await expect(participant.locator('#group-error')).toBeVisible();await participant.locator('#group-send').click();await expect(participant.locator('#group-message')).toHaveValue('');expect(messages.filter(m=>m.body==='Envio com resposta perdida')).toHaveLength(1);
    await owner.locator('#bet-filter').selectOption('mine');await expect(owner.locator('#bet-detail')).toBeHidden();await owner.locator('#bet-filter').selectOption('all');await expect(owner.locator('#bet-detail')).toBeVisible();
    await owner.locator('#group-search').fill('inexistente');await owner.locator('#search-form').evaluate(form=>form.requestSubmit());await expect(owner.locator('#public-groups')).toContainText('Nenhum grupo encontrado.');await owner.locator('#group-search').fill('sexta');await expect(owner.locator('#public-groups')).toContainText('Turma de sexta');await owner.locator('#group-list button').first().click();
    await owner.locator('#add-friend').click();await owner.getByLabel('Nome do usuário',{exact:true}).fill('Ana');await owner.locator('#friend-search-submit').click();await owner.locator('#friend-results').getByRole('button',{name:'Adicionar',exact:true}).click();await expect(owner.locator('#friend-results')).toContainText('Pedido enviado');await owner.keyboard.press('Escape');
    await participant.bringToFront();await participant.evaluate(()=>window.dispatchEvent(new Event('focus')));
    await expect(participant.locator('#friends-list')).toContainText('Quer ser seu amigo',{timeout:20000});await participant.locator('#friends-list').getByRole('button',{name:'Aceitar',exact:true}).click();
    await owner.bringToFront();await owner.evaluate(()=>window.dispatchEvent(new Event('focus')));
    await expect(owner.locator('#friends-list .friend-nav')).toBeVisible({timeout:20000});await owner.locator('#friends-list .friend-nav').click();await expect(owner.locator('#private-message')).toBeEnabled();await expect(owner.locator('#betting-column')).toBeHidden();await owner.locator('#private-message').fill('Oi Ana, mensagem privada');await owner.locator('#private-send').click();await expect(owner.locator('#private-thread')).toContainText('Oi Ana, mensagem privada');
    await participant.locator('#friends-list .friend-nav').click();await expect(participant.locator('#private-thread')).toContainText('Oi Ana, mensagem privada');await participant.locator('#private-message').fill('Oi Marco!');await participant.locator('#private-send').click();await expect(owner.locator('#private-thread')).toContainText('Oi Marco!');await owner.screenshot({path:testInfo.outputPath('private-desktop.png'),fullPage:true});await owner.locator('#group-list button').first().click();await participant.locator('#group-list button').first().click();await expect(participant.locator('#group-thread')).not.toContainText('Oi Ana, mensagem privada');
    const popupPromise=owner.waitForEvent('popup');await owner.getByRole('link',{name:'Outra sessão ↗'}).click();const popup=await popupPromise;await expect(popup.locator('#auth-view')).toBeVisible();await expect(owner.locator('#app-view')).toBeVisible();await popup.close();
    await participant.reload();await expect(participant.locator('.confirmed-box')).toBeVisible();await participant.setViewportSize({width:390,height:844});await participant.screenshot({path:testInfo.outputPath('group-mobile.png'),fullPage:true});expect(await participant.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBeTruthy();
    await participant.locator('#logout-button').click();await expect(participant.locator('#auth-view')).toBeVisible();await expect(owner.locator('#app-view')).toBeVisible();
    expect(errors).toEqual([]);
  }finally{for(const context of contexts)await context.close();}
});
